/**
 * Returns a few-shot reference block for the given niche.
 * Picks a random sample of entries to keep prompt size bounded.
 * Rule: model must treat these as pattern examples, not plots to copy.
 */
export function renderFictionMeReferenceForPrompt(
  linePreset: string,
  sampleSize = 18,
  random: () => number = Math.random,
): string {
  const pool = NICHE_REFERENCE_MAP[linePreset];
  if (!pool || pool.length === 0) return '';
  const shuffled = [...pool].sort(() => random() - 0.5);
  const sample = shuffled.slice(0, Math.min(sampleSize, shuffled.length));
  const lines2 = sample.map((entry, i) => {
    const signals = extractReferenceSignals(entry);
    return [
      `${i + 1}. ref#${pool.indexOf(entry) + 1}`,
      `pressure=${signals.pressure}`,
      `arena=${signals.arena}`,
      `leverage=${signals.leverage}`,
      `reveal=${signals.reveal}`,
      `ending=${signals.ending}`,
    ].join(' | ');
  });
  return [
    `Reference learning samples (${linePreset}) — ${pool.length} crawled stories compressed into structural signals only.`,
    `Use these as market-pattern signals; never reproduce any source title, premise, character setup, scene sequence, or exact relationship chain.`,
    ...lines2,
  ].join('\n');
}

export function buildFictionMeSeedSignalBank(linePreset: string): FictionMeSeedSignalBank | undefined {
  const pool = SEED_SIGNAL_REFERENCE_MAP[linePreset];
  if (!pool || pool.length === 0) return undefined;

  const signals = pool.map(extractReferenceSignals);
  const pressures = unique(signals.map((signal) => signal.pressure));
  const arenas = unique(signals.map((signal) => signal.arena));
  const leverages = unique(signals.map((signal) => signal.leverage));
  const reveals = unique(signals.map((signal) => signal.reveal));
  const endings = unique(signals.map((signal) => signal.ending));
  const compactPairs = unique(signals.map((signal) => `${signal.pressure} through ${signal.leverage}`));

  return {
    linePreset,
    sourceEntryCount: pool.length,
    motifFamilies: compactPairs.map((pair) => `market-tested ${pair} motif transformed for the selected niche`),
    socialPains: pressures.map((pressure) => `market-tested pain of ${pressure} becoming public loss of dignity`),
    arenas: arenas.map((arena) => `market-tested ${arena}`),
    hiddenLeverages: leverages.map((leverage) => `market-tested ${leverage}`),
    evidenceObjects: leverages.map((leverage) => `compressed ${leverage}`),
    betrayerPressures: pressures.map((pressure) => `betrayer escalates because ${pressure} would expose their status lie`),
    statusForces: pressures.map((pressure) => `status system built around ${pressure}`),
    publicRevealVenues: reveals.map((reveal) => `market-tested ${reveal} venue`),
    freshnessAngles: endings.map((ending) => `transform reference-pattern ${ending} into an original non-copy plot spine`),
    relationshipDynamics: compactPairs.map((pair) => `heroine and betrayer locked in ${pair}`),
    protagonistAgencies: leverages.map((leverage) => `waits until the ${leverage} is undeniable before acting`),
    antagonistWebs: pressures.map((pressure) => `family, workplace, or elite allies protecting ${pressure}`),
    revealMechanisms: reveals.map((reveal) => `market-tested ${reveal} converted into fresh evidence logic`),
    endingShapes: endings.map((ending) => `market-tested ${ending} resolved through heroine agency first`),
  };
}

function extractReferenceSignals(entry: FictionMeEntry): FictionMeStructuralSignals {
  const text = `${entry.title} ${entry.premise}`.toLowerCase();
  return {
    pressure: firstMatch(text, [
      ["debt|owe|auction|sold|bought|bid", "debt/sale coercion"],
      ["contract|paper|fake|pretend|convenience", "contract/fake relationship"],
      ["pregnant|twins|baby|child|surrogate", "secret child / heir pressure"],
      ["divorce|ex-wife|ex-husband|regret|comeback", "divorce regret / comeback"],
      ["maid|secretary|assistant|nanny|staff", "workplace/service status gap"],
      ["mafia|crime|underworld|cartel|boss", "underworld control bargain"],
      ["alpha|pack|wolf|mate|luna|king", "dominant bond / hierarchy trial"],
      ["hidden|secret|mistaken|undercover|heiress", "hidden identity reversal"],
    ], "status humiliation"),
    arena: firstMatch(text, [
      ["hotel|suite|penthouse", "luxury private room"],
      ["office|boardroom|ceo|company|corporate", "corporate power room"],
      ["hospital|clinic|doctor|medical", "medical gatekeeping space"],
      ["wedding|chapel|altar|ceremony", "public ritual venue"],
      ["school|campus|university", "elite school / campus"],
      ["mansion|estate|house|home", "family mansion / locked home"],
      ["auction|club|underground|casino", "transaction/underworld venue"],
      ["court|legal|lawyer|contract", "legal pressure room"],
    ], "public status room"),
    leverage: firstMatch(text, [
      ["dna|twins|pregnant|baby|child|birth", "paternity / custody proof"],
      ["contract|paper|clause|license|marriage", "contract clause / legal paper"],
      ["debt|bank|money|auction|sold", "debt ledger / payment trail"],
      ["video|record|camera|evidence|proof", "recording / evidence file"],
      ["inheritance|heir|will|estate|share", "inheritance / ownership record"],
      ["secret|hidden|mistaken|undercover", "identity document / reveal witness"],
    ], "private proof object"),
    reveal: firstMatch(text, [
      ["dna|twins|baby|child", "DNA/custody reveal"],
      ["board|company|ceo|share|inheritance", "boardroom ownership reveal"],
      ["wedding|chapel|altar|ceremony", "ritual interruption reveal"],
      ["video|camera|record|proof", "evidence playback reveal"],
      ["contract|paper|license|clause", "document clause reveal"],
    ], "public proof reversal"),
    ending: firstMatch(text, [
      ["divorce|ex-wife|regret|comeback", "independent comeback before romance"],
      ["pregnant|twins|baby|child", "custody safety before reunion"],
      ["mafia|captive|sold|auction|underworld", "freedom before love choice"],
      ["contract|fake|paper", "contract rewritten as equal terms"],
      ["revenge|betray|expose", "evidence justice, not apology only"],
    ], "status restored with agency"),
  };
}

function unique(values: string[]) {
  return Array.from(new Set(values.filter(Boolean)));
}

function firstMatch(text: string, patterns: Array<[string, string]>, fallback: string) {
  for (const [pattern, label] of patterns) {
    if (new RegExp(pattern, "i").test(text)) {
      return label;
    }
  }
  return fallback;
}
